<?php
require_once __DIR__.'/../includes/db_connect.php';require_once __DIR__.'/../includes/auth.php';requireRole('admin');
$st=$pdo->query("SELECT u.name,u.surname,u.email,c.course_name,COALESCE(p.percentage,0) percentage FROM enrollments e JOIN users u ON u.user_id=e.user_id JOIN courses c ON c.course_id=e.course_id LEFT JOIN progress p ON p.user_id=e.user_id AND p.course_id=e.course_id ORDER BY c.course_name,u.name");$rows=$st->fetchAll();$pageTitle='Progress Overview';require __DIR__.'/../includes/header.php';
?><div class="page-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>Progress Overview</h1><p>Monitor learner course progress across the LMS.</p></div></div><section class="dashboard-card"><div class="table-container"><table><thead><tr><th>Learner</th><th>Email</th><th>Course</th><th>Progress</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">No enrollments yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['name'].' '.$r['surname'])?></td><td><?=e($r['email'])?></td><td><?=e($r['course_name'])?></td><td><strong><?=e($r['percentage'])?>%</strong></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
